//! The radiotap header, as specified at https://www.radiotap.org/ : an 8-bit
//! version (always 0), one pad octet, a 16-bit little-endian length covering the
//! whole radiotap header, and a 32-bit little-endian present bitmap which is
//! extended by further words while bit 31 is set. The length field, not the
//! bitmap, is what bounds the header.
//!
//! Generated by dev/protogen from dev/protogen/specs/radiotap.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{Next, ProtoDesc, ProtoId};

// protogen:hand begin
/// The it_len word bounds the header; the present bitmap may be extended by
/// further words and does not.
fn header_len(hdr: &[u8]) -> usize {
    match hdr.get(2..4) {
        Some(b) => (u16::from_le_bytes([b[0], b[1]]) as usize).max(8),
        None => 8,
    }
}

fn next(_: &[u8]) -> Next {
    Next::Proto(ProtoId::Dot11)
}
// protogen:hand end

pub static FIELDS: &[FieldDesc] = &[
    FieldDesc::uint("version", 0, 8, 0),
    FieldDesc::uint("pad", 8, 8, 0),
    FieldDesc::le_uint("len", 16, 16, 8),
    FieldDesc::le_uint("present", 32, 32, 0),
];

pub static DESC: ProtoDesc = ProtoDesc {
    id: ProtoId::RadioTap,
    name: "RadioTap",
    fields: FIELDS,
    min_len: 8,
    header_len,
    next,
    build_len: 8,
    parse_options: None,
    opt_table: None,
    set_hlen: None,
    bind_next: None,
    bind_next_bytes: None,
    content_len: None,
};

#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// radiotap.org: a header with no present fields, length 8.
    fn vector() -> Vec<u8> {
        vec![0x00, 0x00, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::RadioTap);
        let l = p.find_layer(ProtoId::RadioTap).unwrap();
        assert_eq!(p.get(l, "version").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "pad").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "len").unwrap(), FieldValue::Uint(8));
        assert_eq!(p.get(l, "present").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::RadioTap);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::RadioTap);
        let l = p.find_layer(ProtoId::RadioTap).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::RadioTap, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
